}

@namespace sv_067b76d0c7ae4617b9ab692b40cef7b2.Components.Pages.Catalog

<aside class="catalog-sidebar" style="padding:1rem;border-right:1px solid #ddd;">
    <h3>Filters</h3>

    <div class="filter-section" style="margin-bottom:1.5rem;">
        <h5>Categories</h5>
        @foreach (var category in Categories)
        {
            <label style="display:block;margin-bottom:0.3rem;">
                <input type="checkbox" checked="@IsSelected(category)" @onchange="(e) => ToggleCategory(category, (bool)e.Value!)" />
                @category
            </label>
        }
    </div>

    <div class="filter-section" style="margin-bottom:1.5rem;">
        <h5>Price Range</h5>
        <label style="display:block;margin-bottom:0.5rem;">
            Min:
            <input type="number" min="0" step="0.01" value="@MinPrice" @onchange="(e) => MinPrice = ParseDecimal(e.Value)" style="width:100%;padding:0.3rem;" />
        </label>
        <label style="display:block;">
            Max:
            <input type="number" min="0" step="0.01" value="@MaxPrice" @onchange="(e) => MaxPrice = ParseDecimal(e.Value)" style="width:100%;padding:0.3rem;" />
        </label>
    </div>

    <div class="filter-section" style="margin-bottom:1.5rem;">
        <label style="display:block;">
            <input type="checkbox" @bind="InStockOnly" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions" style="display:flex;flex-direction:column;gap:0.5rem;">
        <button @onclick="ApplyFilters" style="padding:0.5rem;background:#0d6efd;color:#fff;border:none;border-radius:4px;cursor:pointer;">
            Apply Filters
        </button>
        <button @onclick="ClearFilters" style="padding:0.5rem;background:#6c757d;color:#fff;border:none;border-radius:4px;cursor:pointer;">
            Clear Filters
        </button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = new();

    [Parameter]
    public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private List<string> _selectedCategories = new();
    private decimal? MinPrice;
    private decimal? MaxPrice;
    private bool InStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked && !_selectedCategories.Contains(category))
            _selectedCategories.Add(category);
        else if (!isChecked)
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? new List<string>(_selectedCategories) : null,
            MinPrice: MinPrice,
            MaxPrice: MaxPrice,
            InStockOnly: InStockOnly
        );
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        MinPrice = null;
        MaxPrice = null;
        InStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }

    private decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_067b76d0c7ae4617b9ab692b40cef7b2.Components.Pages.Catalog

<div class="catalog-toolbar" style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem;padding:0.5rem 0;">
    <div>
        <label>
            Sort by:
            <select value="@SortBy" @onchange="HandleSortChanged" style="padding:0.3rem;border-radius:4px;border:1px solid #ccc;">
                <option value="price_asc">Price: Low to High</option>
                <option value="price_desc">Price: High to Low</option>
                <option value="name_asc">Name: A-Z</option>
                <option value="rating_desc">Rating: Highest</option>
            </select>
        </label>
    </div>
    <div class="results-info">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <span>Showing @start–@end of @TotalCount products</span>
        }
    </div>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_067b76d0c7ae4617b9ab692b40cef7b2.Components.Pages.Catalog

<nav class="catalog-pagination" style="display:flex;justify-content:center;align-items:center;gap:0.5rem;margin-top:1.5rem;">
    <button disabled="@(CurrentPage <= 1)" @onclick="() => GoToPage(CurrentPage - 1)"
            style="padding:0.4rem 0.8rem;border:1px solid #ccc;border-radius:4px;cursor:pointer;">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var page = i;
        <button @onclick="() => GoToPage(page)"
                style="padding:0.4rem 0.8rem;border:1px solid #ccc;border-radius:4px;cursor:pointer;@(page == CurrentPage ? "background:#0d6efd;color:#fff;border-color:#0d6efd;" : "")">
            @page
        </button>
    }

    <button disabled="@(CurrentPage >= TotalPages)" @onclick="() => GoToPage(CurrentPage + 1)"
            style="padding:0.4rem 0.8rem;border:1px solid #ccc;border-radius:4px;cursor:pointer;">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; } = 1;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}

@page "/catalog"
@namespace sv_067b76d0c7ae4617b9ab692b40cef7b2.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-page" style="display:flex;gap:1.5rem;padding:1rem;">
    <div style="flex:0 0 25%;max-width:25%;">
        <CatalogSidebar Categories="_categories"
                        OnFilterApplied="HandleFilterApplied"
                        OnFilterCleared="HandleFilterCleared" />
    </div>

    <div style="flex:1;">
        @if (_loading)
        {
            <div class="loading-state" style="text-align:center;padding:3rem;">
                <p>Loading products...</p>
            </div>
        }
        else if (_error is not null)
        {
            <div class="error-state" style="text-align:center;padding:3rem;color:#dc3545;">
                <p>Error loading products: @_error</p>
                <button @onclick="LoadProducts" style="padding:0.5rem 1rem;border:none;border-radius:4px;background:#0d6efd;color:#fff;cursor:pointer;">
                    Retry
                </button>
            </div>
        }
        else if (_result is not null && _result.Items.Count == 0)
        {
            <div class="empty-state" style="text-align:center;padding:3rem;">
                <p>No products found matching your filters.</p>
            </div>
        }
        else if (_result is not null)
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="_result.TotalCount"
                            Page="_currentPage"
                            PageSize="_pageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="_result.Items"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            @if (_totalPages > 1)
            {
                <CatalogPagination CurrentPage="_currentPage"
                                   TotalPages="_totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        }
    </div>
</div>

@code {
    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    private List<string> _categories = new();
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _pageSize = 12;
    private bool _loading;
    private string? _error;
    private int _totalPages => _result is null ? 1 : (int)Math.Ceiling((double)_result.TotalCount / _pageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await LoadProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            _categories = new();
        }
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;
        StateHasChanged();

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, _pageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleFilterCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(int productId)
    {
        await OnProductSelected.InvokeAsync(productId);
    }

    private Task HandleAddToCart(int productId)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

