        <span class="out-of-stock-badge" style="background:#dc3545;color:#fff;padding:0.2rem 0.5rem;border-radius:4px;font-size:0.8rem;align-self:flex-start;">Out of Stock</span>
    }
    <button class="add-to-cart-btn" disabled="@(!Product.InStock)" @onclick="HandleAddToCart" @onclick:stopPropagation="true"
            style="margin-top:auto;padding:0.5rem;border:none;border-radius:4px;background:@(Product.InStock ? "#0d6efd" : "#6c757d");color:#fff;cursor:@(Product.InStock ? "pointer" : "not-allowed");">
        Add to Cart
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<int> OnAddToCart { get; set; }

    private string GetStarRating()
    {
        int filled = (int)Math.Round(Product.Rating);
        return new string('★', filled) + new string('☆', 5 - filled);
    }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product.Id);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product.Id);
    }
}

